import type { MutationGrantDefinition } from "../../../../types/mutants-handbook";
import type { WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";

export interface MutationGrantOwner {
  grantKey: string;
  ownerId: string;
}

export interface MutationGrantOwnership {
  managed: boolean;
  owners: MutationGrantOwner[];
  signature: string;
  sourceUuid: string;
  version: 2;
}

export interface MutationSkillGrantOwner extends MutationGrantOwner {
  ranks: number;
  signature: string;
  sourceUuid: string;
}

export interface MutationSkillGrantLedger {
  appliedRanks: number;
  managed: boolean;
  owners: MutationSkillGrantOwner[];
  version: 1;
}

function canonicalValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(canonicalValue);
  }

  if (typeof value === "object" && value !== null) {
    return Object.fromEntries(
      Object.entries(value)
        .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
        .map(([key, entry]) => [key, canonicalValue(entry)]),
    );
  }

  return value;
}

export function mutationGrantSignature(grant: MutationGrantDefinition): string {
  return JSON.stringify(
    canonicalValue({
      configure: grant.configure ?? {},
      ranks: grant.ranks ?? 1,
      scope: grant.scope ?? "all",
      sourceUuid: grant.sourceUuid,
      stack: grant.stack ?? "singleton",
      type: grant.type,
    }),
  );
}

export function mutationRankGrantIdentity(grant: MutationGrantDefinition): string {
  const identityGrant = { ...grant };
  delete identityGrant.scope;
  return mutationGrantSignature({ ...identityGrant, ranks: 1 });
}

export function mutationRankGrantIdentityFromSignature(signature: string): string | undefined {
  let value: unknown;
  try {
    value = JSON.parse(signature);
  } catch {
    return undefined;
  }
  if (typeof value !== "object" || value === null || Array.isArray(value)) return undefined;
  const parsed = value as Record<string, unknown>;
  if (parsed["stack"] !== "rank" || (parsed["type"] !== "skill" && parsed["type"] !== "talent")) {
    return undefined;
  }
  parsed["ranks"] = 1;
  parsed["scope"] = "all";
  return JSON.stringify(canonicalValue(parsed));
}

function getPath(object: Record<string, unknown>, path: string): unknown {
  let current: unknown = object;

  for (const part of path.split(".")) {
    if (typeof current !== "object" || current === null) {
      return undefined;
    }
    current = (current as Record<string, unknown>)[part];
  }

  return current;
}

function setPath(object: Record<string, unknown>, path: string, value: unknown): void {
  const parts = path.split(".").filter(Boolean);
  const unsafe = new Set(["__proto__", "constructor", "prototype"]);

  if (parts.length === 0 || parts.some((part) => unsafe.has(part))) {
    throw new Error(`Unsafe mutation grant configuration path: ${path}.`);
  }

  let current = object;
  for (const part of parts.slice(0, -1)) {
    const child = current[part];
    if (typeof child !== "object" || child === null || Array.isArray(child)) {
      current[part] = {};
    }
    current = current[part] as Record<string, unknown>;
  }
  current[parts.at(-1) as string] = value;
}

export function configureGrantData(
  data: Record<string, unknown>,
  grant: MutationGrantDefinition,
): Record<string, unknown> {
  if (grant.configure?.name) {
    data["name"] = grant.configure.name;
  }

  const system = data["system"];
  const configuredSystem =
    typeof system === "object" && system !== null ? (system as Record<string, unknown>) : {};
  data["system"] = configuredSystem;

  for (const [rawPath, value] of Object.entries(grant.configure?.system ?? {})) {
    setPath(configuredSystem, rawPath.replace(/^system\./, ""), canonicalValue(value));
  }

  if (grant.ranks !== undefined && (grant.type === "skill" || grant.type === "talent")) {
    setPath(configuredSystem, "advances.value", grant.ranks);
  }

  return data;
}

export function grantDataMatches(
  item: WfrpMutationItem,
  source: WfrpMutationItem,
  grant: MutationGrantDefinition,
): boolean {
  if (item.type !== grant.type) return false;

  const data = item.toObject();
  const expectedName = grant.configure?.name ?? source.name;
  if (data["name"] !== expectedName) return false;

  const system = data["system"];
  if (typeof system !== "object" || system === null) return false;

  for (const [rawPath, value] of Object.entries(grant.configure?.system ?? {})) {
    const path = rawPath.replace(/^system\./, "");
    if (
      JSON.stringify(canonicalValue(getPath(system as Record<string, unknown>, path))) !==
      JSON.stringify(canonicalValue(value))
    ) {
      return false;
    }
  }

  if (
    grant.ranks !== undefined &&
    (grant.type === "skill" || grant.type === "talent") &&
    Number(getPath(system as Record<string, unknown>, "advances.value")) !== grant.ranks
  ) {
    return false;
  }

  return true;
}

export function hasMatchingSourceIdentity(item: WfrpMutationItem, sourceUuid: string): boolean {
  const stats = item.toObject()["_stats"];
  if (typeof stats !== "object" || stats === null) return false;
  return (stats as Record<string, unknown>)["compendiumSource"] === sourceUuid;
}

export function getGrantOwnership(item: WfrpMutationItem): MutationGrantOwnership | undefined {
  const value = item.flags?.[MODULE_ID]?.["mutationGrant"];
  if (typeof value !== "object" || value === null) return undefined;

  const candidate = value as Partial<MutationGrantOwnership>;
  if (
    candidate.version !== 2 ||
    typeof candidate.managed !== "boolean" ||
    typeof candidate.signature !== "string" ||
    typeof candidate.sourceUuid !== "string" ||
    !Array.isArray(candidate.owners)
  ) {
    return undefined;
  }

  const owners = candidate.owners.filter(
    (owner): owner is MutationGrantOwner =>
      typeof owner === "object" &&
      owner !== null &&
      typeof owner.grantKey === "string" &&
      typeof owner.ownerId === "string",
  );

  return { ...candidate, owners } as MutationGrantOwnership;
}

export function getLegacyGrantOwners(item: WfrpMutationItem): string[] {
  const value = item.flags?.[MODULE_ID]?.["mutationGrantOwners"];
  return Array.isArray(value)
    ? value.filter((owner): owner is string => typeof owner === "string")
    : [];
}

export function isLegacyManagedGrant(item: WfrpMutationItem): boolean {
  return item.flags?.[MODULE_ID]?.["mutationGrantManaged"] === true;
}

export function getSkillGrantLedger(item: WfrpMutationItem): MutationSkillGrantLedger | undefined {
  const value = item.flags?.[MODULE_ID]?.["mutationSkillGrant"];
  if (typeof value !== "object" || value === null) return undefined;

  const candidate = value as Partial<MutationSkillGrantLedger>;
  if (
    candidate.version !== 1 ||
    typeof candidate.managed !== "boolean" ||
    !Number.isFinite(candidate.appliedRanks) ||
    (candidate.appliedRanks ?? -1) < 0 ||
    !Array.isArray(candidate.owners)
  ) {
    return undefined;
  }

  const owners = candidate.owners.filter(
    (owner): owner is MutationSkillGrantOwner =>
      typeof owner === "object" &&
      owner !== null &&
      typeof owner.grantKey === "string" &&
      typeof owner.ownerId === "string" &&
      Number.isFinite(owner.ranks) &&
      owner.ranks > 0 &&
      typeof owner.signature === "string" &&
      typeof owner.sourceUuid === "string",
  );
  if (owners.length !== candidate.owners.length) return undefined;

  return { ...candidate, owners } as MutationSkillGrantLedger;
}
