import type { WfrpActor, WfrpMutationItem } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { MUTATION_RETIRED_FLAG, POSSESSION_REMOVED_FLAG } from "./constants";

export interface ActorItemLike {
  getFlag?: (scope: string, key: string) => unknown;
  id?: string;
  name?: string;
  system?: unknown;
  type?: string;
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function normalizeName(value: string): string {
  return value.trim().toLowerCase();
}

function itemFlag(item: ActorItemLike, key: string): unknown {
  return typeof item.getFlag === "function" ? item.getFlag(MODULE_ID, key) : undefined;
}

function actorItems(actor: WfrpActor): ActorItemLike[] {
  const itemTypes = actor.itemTypes as unknown as Record<string, ActorItemLike[] | undefined>;
  const typed = Object.values(itemTypes ?? {}).flatMap((items) => items ?? []);
  let collected: ActorItemLike[] = [];
  try {
    collected = Array.from(actor.items as unknown as Iterable<ActorItemLike>);
  } catch {
    // Some test doubles and older system documents expose only itemTypes.
  }
  return [...collected, ...typed].filter(
    (item, index, items) =>
      items.findIndex(
        (candidate) =>
          candidate === item ||
          (typeof item.id === "string" && item.id.length > 0 && candidate.id === item.id),
      ) === index,
  );
}

export function isMutationRetired(item: WfrpMutationItem): boolean {
  return (
    item.getFlag(MODULE_ID, MUTATION_RETIRED_FLAG) === true ||
    item.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) === true
  );
}

export function activeMutations(actor: WfrpActor, ignoreItemId?: string): WfrpMutationItem[] {
  return (actor.itemTypes.mutation ?? []).filter(
    (item) => (ignoreItemId === undefined || item.id !== ignoreItemId) && !isMutationRetired(item),
  );
}

export function selectionValues(value: unknown): string[] {
  if (typeof value === "string") return [normalizeName(value)];
  return Array.isArray(value)
    ? value.filter((entry): entry is string => typeof entry === "string").map(normalizeName)
    : [];
}

export function resolvedSelections(item: ActorItemLike): Record<string, unknown> | undefined {
  const automation = itemFlag(item, "mutationAutomation");
  if (!isRecord(automation)) return undefined;
  const state = automation["state"];
  if (!isRecord(state)) return undefined;
  const acquisition = state["acquisition"];
  if (!isRecord(acquisition) || acquisition["status"] !== "resolved") return undefined;
  return isRecord(acquisition["selections"]) ? acquisition["selections"] : undefined;
}

export function hasResolvedSelection(
  item: ActorItemLike,
  key: string,
  values: readonly string[],
): boolean {
  const selections = resolvedSelections(item);
  if (!selections) return false;
  const expected = new Set(values.map(normalizeName));
  return selectionValues(selections[key]).some((value) => expected.has(value));
}

export function activeMutationNamed(
  actor: WfrpActor,
  name: string,
  ignoreItemId?: string,
): WfrpMutationItem | undefined {
  const normalized = normalizeName(name);
  return activeMutations(actor, ignoreItemId).find(
    (item) => normalizeName(item.name) === normalized,
  );
}

export function hasTalent(actor: WfrpActor, baseName: string): boolean {
  const normalized = normalizeName(baseName);
  return actorItems(actor).some((item) => {
    if (item.type !== "talent" || typeof item.name !== "string") return false;
    const name = normalizeName(item.name);
    return name === normalized || name.startsWith(`${normalized} (`);
  });
}

function propertyValue(value: unknown, path: readonly string[]): unknown {
  let current = value;
  for (const key of path) {
    if (!isRecord(current)) return undefined;
    current = current[key];
  }
  return current;
}

export function currentCareerGroup(actor: WfrpActor): string | undefined {
  const direct = (actor as unknown as Record<string, unknown>)["currentCareer"];
  const careers = [
    ...(isRecord(direct) ? [direct] : []),
    ...actorItems(actor).filter(
      (item) => item.type === "career" && propertyValue(item.system, ["current", "value"]) === true,
    ),
  ];
  for (const career of careers) {
    const group = propertyValue(career, ["system", "careergroup", "value"]);
    if (typeof group === "string" && group.trim().length > 0) return normalizeName(group);
  }
  return undefined;
}

export function hasEligibleAdditionalLegs(actor: WfrpActor, ignoreItemId?: string): boolean {
  return activeMutations(actor, ignoreItemId).some(
    (item) =>
      ["additional extremities", "additional limbs"].includes(normalizeName(item.name)) &&
      hasResolvedSelection(item, "limb", ["legs"]),
  );
}

export function hasResolvedAdditionalArms(actor: WfrpActor, ignoreItemId?: string): boolean {
  return activeMutations(actor, ignoreItemId).some(
    (item) =>
      ["additional extremities", "additional limbs"].includes(normalizeName(item.name)) &&
      hasResolvedSelection(item, "limb", ["arms"]),
  );
}
