import type { WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";
import { retireSkinwalkerMutations } from "../documents";
import { clearMutationFormForMutation } from "../actions/forms";
import type { MutationActionActor } from "../actions/types";
import { reportMutationError } from "../messages";
import { finalizePendingMutationDrop } from "../mutation-drop";
import { readPendingMutation } from "../pending-corruption";
import { reconcileMutationAutomation, removeMutationGrantOwner } from "./grant-reconciliation";

function automatedOwnedMutation(value: unknown): WfrpMutationItem | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const item = value as Partial<WfrpMutationItem>;
  if (
    item.type !== "mutation" ||
    typeof item.id !== "string" ||
    typeof item.actor?.uuid !== "string"
  ) {
    return undefined;
  }
  const automation = item.flags?.[MODULE_ID]?.["mutationAutomation"];
  return typeof automation === "object" && automation !== null
    ? (item as WfrpMutationItem)
    : undefined;
}

function mutationSupportingItem(value: unknown): WfrpMutationItem | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const item = value as Partial<WfrpMutationItem>;
  if (typeof item.id !== "string" || typeof item.actor?.uuid !== "string") return undefined;
  const flags = item.flags?.[MODULE_ID];
  return typeof flags?.["mutationGrant"] === "object" ||
    typeof flags?.["mutationSkillGrant"] === "object"
    ? (item as WfrpMutationItem)
    : undefined;
}

function pendingOwnedMutation(value: unknown): WfrpMutationItem | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const item = value as Partial<WfrpMutationItem>;
  if (
    item.type !== "mutation" ||
    typeof item.id !== "string" ||
    typeof item.actor?.uuid !== "string" ||
    typeof item.getFlag !== "function"
  ) {
    return undefined;
  }
  return readPendingMutation(item as WfrpMutationItem) ? (item as WfrpMutationItem) : undefined;
}

function reportRejected(operation: Promise<void>): void {
  void operation.catch(reportMutationError);
}

function mutationDefinitionId(mutation: WfrpMutationItem): string | undefined {
  const automation = mutation.flags?.[MODULE_ID]?.["mutationAutomation"];
  return typeof automation === "object" &&
    automation !== null &&
    typeof (automation as Record<string, unknown>)["definitionId"] === "string"
    ? ((automation as Record<string, unknown>)["definitionId"] as string)
    : undefined;
}

async function removeMutationRuntime(mutation: WfrpMutationItem): Promise<void> {
  const definitionId = mutationDefinitionId(mutation);
  if (definitionId && mutation.actor) {
    await clearMutationFormForMutation(
      mutation.actor as unknown as MutationActionActor,
      definitionId,
    );
  }
  if (mutation.actor) await removeMutationGrantOwner(mutation.actor.uuid, mutation.id);
}

export function isMutationAutomationHookAuthority(userId: unknown): boolean {
  return typeof userId === "string" && game?.user.id === userId;
}

export async function finalizeCreatedMutationAutomation(
  mutation: WfrpMutationItem,
  options: Record<string, unknown> = {},
): Promise<void> {
  if (!mutation.actor) return;
  const finalizedPendingDrop = await finalizePendingMutationDrop(mutation);
  if (
    !finalizedPendingDrop &&
    mutation.name.trim().toLowerCase() === "chimeran curse" &&
    options["mutationAcquisitionHandlesChimeranRetirement"] !== true
  ) {
    await retireSkinwalkerMutations(mutation.actor);
  }
}

export function registerMutationAutomationHooks(): void {
  Hooks.on("createItem", (document, options, userId) => {
    if (!isMutationAutomationHookAuthority(userId)) return;
    const mutation = automatedOwnedMutation(document) ?? pendingOwnedMutation(document);
    if (mutation?.actor) {
      reportRejected(
        finalizeCreatedMutationAutomation(
          mutation,
          typeof options === "object" && options !== null
            ? (options as Record<string, unknown>)
            : {},
        ),
      );
    }
  });

  Hooks.on("deleteItem", (document, _options, userId) => {
    if (!isMutationAutomationHookAuthority(userId)) return;
    const mutation = automatedOwnedMutation(document);
    if (mutation?.actor) {
      reportRejected(removeMutationRuntime(mutation));
      return;
    }
    const supportingItem = mutationSupportingItem(document);
    if (supportingItem?.actor) {
      reportRejected(reconcileMutationAutomation(supportingItem.actor.uuid));
    }
  });

  Hooks.on("updateItem", (document, _changes, _options, userId) => {
    if (!isMutationAutomationHookAuthority(userId)) return;
    const mutation = automatedOwnedMutation(document);
    const flags = mutation?.flags?.[MODULE_ID];
    if (
      mutation?.actor &&
      (flags?.["mutantsHandbookRetired"] === true ||
        flags?.["mutantsHandbookPossessionRemoved"] === true)
    ) {
      reportRejected(removeMutationRuntime(mutation));
    }
  });
}
