import type { WfrpMutationItem } from "../../../../../types/foundry";
import {
  getGrantOwnership,
  mutationRankGrantIdentityFromSignature,
  type MutationSkillGrantOwner,
} from "../grant-data";
import { baseAdvances, rankedSignatureData } from "../ranked-skill-items";

export interface RankedGrantData {
  appliedRanks: number;
  legacy: boolean;
  managed: boolean;
  owners: MutationSkillGrantOwner[];
}

function legacyRankedTalent(item: WfrpMutationItem): RankedGrantData | undefined {
  if (item.type !== "talent") return undefined;
  const ownership = getGrantOwnership(item);
  if (!ownership || !mutationRankGrantIdentityFromSignature(ownership.signature)) return undefined;
  let ranks = 0;
  try {
    ranks = Number((JSON.parse(ownership.signature) as Record<string, unknown>)["ranks"]);
  } catch {
    return undefined;
  }
  if (!Number.isFinite(ranks) || ranks <= 0) return undefined;
  return {
    appliedRanks: ranks * ownership.owners.length,
    legacy: true,
    managed: ownership.managed,
    owners: ownership.owners.map((owner) => ({
      ...owner,
      ranks,
      signature: ownership.signature,
      sourceUuid: ownership.sourceUuid,
    })),
  };
}

export function rankedGrantData(item: WfrpMutationItem): RankedGrantData | undefined {
  return rankedSignatureData(item) ?? legacyRankedTalent(item);
}

export function rankedBaseAdvances(item: WfrpMutationItem, desiredRanks?: number): number {
  const ranked = legacyRankedTalent(item);
  if (!ranked) return baseAdvances(item, desiredRanks);
  const system = item.toObject()["system"] as Record<string, Record<string, unknown>> | undefined;
  const advances = Number(system?.["advances"]?.["value"] ?? 0);
  const applied =
    desiredRanks === undefined
      ? ranked.appliedRanks
      : Math.max(ranked.appliedRanks, Math.min(desiredRanks, advances));
  return Math.max(0, advances - applied);
}

export function rankedPriority(item: WfrpMutationItem): number {
  const ranked = rankedGrantData(item);
  if (ranked?.managed === false) return 0;
  return ranked ? 2 : 1;
}

export function hasRankedIdentity(item: WfrpMutationItem, identity: string): boolean {
  return (
    rankedGrantData(item)?.owners.some(
      (owner) => mutationRankGrantIdentityFromSignature(owner.signature) === identity,
    ) ?? false
  );
}
