import { getCorruptionLoss, getReducedCorruption } from "../../../functions/mutants-handbook/rules";
import type {
  CharacteristicBonuses,
  ChosenPatron,
  MutationNature,
} from "../../../types/mutants-handbook";
import type { WfrpActor } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { chooseChaosPatron, spendResilience } from "./dialogs";
import { reconcileMutationAutomation } from "./automation/grant-reconciliation";
import { hasPossessedMutation, retirePossessedMutations } from "./documents";
import { formatMutationMessage, postMutationMessage, warnAboutMutation } from "./messages";
import { CHOSEN_PATRON_FLAG } from "./constants";
import { updateActor } from "./updates";

const chosenPatronPath = `flags.${MODULE_ID}.${CHOSEN_PATRON_FLAG}`;

function getBonuses(actor: WfrpActor): CharacteristicBonuses {
  return {
    toughness: Number(actor.system.characteristics.t.bonus),
    willpower: Number(actor.system.characteristics.wp.bonus),
  };
}

function getActorCorruptionLoss(actor: WfrpActor, nature: MutationNature): number {
  return getCorruptionLoss(nature, getBonuses(actor));
}

function displayName(value: string): string {
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

async function shouldSpendResilience(actor: WfrpActor, outcomeName: string): Promise<boolean> {
  const resilience = Number(actor.system.status.resilience.value);
  return resilience > 0 && (await spendResilience(actor.name, outcomeName));
}

async function updateAfterMutationRoll(
  actor: WfrpActor,
  loss: number,
  spend: boolean,
  additionalChanges: Record<string, unknown> = {},
): Promise<void> {
  const changes: Record<string, unknown> = {
    ...additionalChanges,
    "system.status.corruption.value": getReducedCorruption(
      Number(actor.system.status.corruption.value),
      loss,
    ),
  };

  if (spend) {
    changes["system.status.resilience.value"] = Math.max(
      0,
      Number(actor.system.status.resilience.value) - 1,
    );
  }

  await updateActor(actor, changes);
}

export async function applyChosen(actor: WfrpActor, nature: MutationNature): Promise<void> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while applying Chosen of Chaos.");
  }

  const outcomeName = game.i18n.localize("FVTT_WFRP_RATTER.Mutations.ChosenOutcome");
  const spend = await shouldSpendResilience(actor, outcomeName);

  if (spend) {
    const loss = getActorCorruptionLoss(actor, nature);
    await updateAfterMutationRoll(actor, loss, true);
    await postMutationMessage(
      formatMutationMessage("Resisted", {
        loss,
        mutation: outcomeName,
        name: actor.name,
      }),
    );
    return;
  }

  const patron = await chooseChaosPatron(actor.name);
  const chosenPatron: ChosenPatron = patron ?? "unassigned";
  const hadPossessedMutation = hasPossessedMutation(actor);
  const loss = getActorCorruptionLoss(actor, nature);
  await updateAfterMutationRoll(actor, loss, false, {
    [chosenPatronPath]: chosenPatron,
  });
  if (hadPossessedMutation) {
    await retirePossessedMutations(actor);
    await reconcileMutationAutomation(actor.uuid);
  }

  const messageKey = patron ? "Chosen" : "ChosenUnassigned";
  await postMutationMessage(
    formatMutationMessage(messageKey, {
      loss,
      name: actor.name,
      patron: patron ? displayName(patron) : "Chaos",
    }),
  );

  if (hadPossessedMutation) {
    const possessedMessage = formatMutationMessage("PossessedRemoved", { name: actor.name });
    warnAboutMutation(possessedMessage);
    await postMutationMessage(possessedMessage);
  }
}
