import type { FoundryScene, WfrpActor, WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";
import { reconcileMutationAutomation } from "./grant-reconciliation";

const MUTATION_ITEM_PACK = `${MODULE_ID}.ratter-11-items`;
const MUTANTS_HANDBOOK_SOURCE = "The Mutant's Handbook";
const DEFINITION_FLAG_KEYS = new Set([
  "acquisition",
  "actions",
  "automated",
  "definitionId",
  "grants",
  "manual",
  "retainedRolls",
  "selfControl",
  "status",
  "version",
]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function itemData(item: WfrpMutationItem): Record<string, unknown> {
  return item.toObject();
}

function moduleFlags(data: Record<string, unknown>): Record<string, unknown> {
  const flags = data["flags"];
  if (!isRecord(flags)) return {};
  const value = flags[MODULE_ID];
  return isRecord(value) ? value : {};
}

function effects(data: Record<string, unknown>): Record<string, unknown>[] {
  const value = data["effects"];
  return Array.isArray(value) ? value.filter(isRecord) : [];
}

function canonicalValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalValue);
  if (!isRecord(value)) return value;

  return Object.fromEntries(
    Object.entries(value)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, entry]) => [key, canonicalValue(entry)]),
  );
}

function valuesEqual(left: unknown, right: unknown): boolean {
  return JSON.stringify(canonicalValue(left)) === JSON.stringify(canonicalValue(right));
}

function comparableEffect(effect: Record<string, unknown>): Record<string, unknown> {
  const comparable = { ...effect };
  delete comparable["_key"];
  delete comparable["_stats"];
  return comparable;
}

export function isManagedMutationAutomationEffect(effect: Record<string, unknown>): boolean {
  const flags = effect["flags"];
  if (!isRecord(flags)) return false;
  const value = flags[MODULE_ID];
  return isRecord(value) && typeof value["automationPhase"] === "string";
}

function mergedAutomationFlag(
  current: unknown,
  latest: Record<string, unknown>,
): Record<string, unknown> {
  if (!isRecord(current)) return latest;

  const runtimeState = Object.fromEntries(
    Object.entries(current).filter(([key]) => !DEFINITION_FLAG_KEYS.has(key)),
  );
  return { ...latest, ...runtimeState };
}

export function prepareOwnedMutationAutomationUpdate(
  owned: Record<string, unknown>,
  source: Record<string, unknown>,
): Record<string, unknown> | undefined {
  const latestAutomation = moduleFlags(source)["mutationAutomation"];
  if (!isRecord(latestAutomation)) return undefined;

  const currentAutomation = moduleFlags(owned)["mutationAutomation"];
  const desiredAutomation = mergedAutomationFlag(currentAutomation, latestAutomation);
  const currentManagedEffects = effects(owned).filter(isManagedMutationAutomationEffect);
  const latestManagedEffects = effects(source).filter(isManagedMutationAutomationEffect);
  const desiredEffects = [
    ...latestManagedEffects,
    ...effects(owned).filter((effect) => !isManagedMutationAutomationEffect(effect)),
  ];
  const update: Record<string, unknown> = {};

  if (!valuesEqual(currentAutomation, desiredAutomation)) {
    update[`flags.${MODULE_ID}.mutationAutomation`] = desiredAutomation;
  }
  if (
    !valuesEqual(
      currentManagedEffects.map(comparableEffect),
      latestManagedEffects.map(comparableEffect),
    )
  ) {
    update["effects"] = desiredEffects;
  }

  return Object.keys(update).length > 0 ? update : undefined;
}

function isMutationItem(value: unknown): value is WfrpMutationItem {
  if (!isRecord(value)) return false;
  return (
    value["type"] === "mutation" &&
    typeof value["id"] === "string" &&
    typeof value["name"] === "string" &&
    typeof value["toObject"] === "function"
  );
}

function definitionId(item: WfrpMutationItem): string | undefined {
  const automation = moduleFlags(itemData(item))["mutationAutomation"];
  return isRecord(automation) && typeof automation["definitionId"] === "string"
    ? automation["definitionId"]
    : undefined;
}

function isHandbookMutation(item: WfrpMutationItem): boolean {
  return moduleFlags(itemData(item))["sourceDocument"] === MUTANTS_HANDBOOK_SOURCE;
}

export function collectMutationMigrationActors(
  worldActors: Iterable<WfrpActor>,
  scenes: Iterable<FoundryScene>,
): WfrpActor[] {
  const actors = new Map<string, WfrpActor>();
  for (const actor of worldActors) actors.set(actor.uuid, actor);
  for (const scene of scenes) {
    for (const token of scene.tokens ?? []) {
      if (token.actor) actors.set(token.actor.uuid, token.actor);
    }
  }
  return [...actors.values()];
}

async function replaceManagedEffects(
  owned: WfrpMutationItem,
  source: WfrpMutationItem,
): Promise<void> {
  if (!owned.deleteEmbeddedDocuments || !owned.createEmbeddedDocuments) {
    throw new Error(`${owned.name} does not support embedded Active Effect migration.`);
  }

  const managed = effects(itemData(owned)).filter(isManagedMutationAutomationEffect);
  const deleteIds = managed
    .map((effect) => effect["_id"])
    .filter((id): id is string => typeof id === "string");
  if (deleteIds.length !== managed.length) {
    throw new Error(`${owned.name} has a managed Active Effect without an ID.`);
  }
  if (deleteIds.length > 0) {
    await owned.deleteEmbeddedDocuments("ActiveEffect", deleteIds);
  }

  const latest = effects(itemData(source))
    .filter(isManagedMutationAutomationEffect)
    .map((effect) => {
      const data = { ...effect };
      delete data["_key"];
      return data;
    });
  if (latest.length > 0) {
    await owned.createEmbeddedDocuments("ActiveEffect", latest, {
      keepId: true,
      skipMutationAcquisition: true,
    });
  }
}

export async function migrateOwnedMutationAutomation(): Promise<void> {
  if (!game || game.user.isUniqueGM !== true) return;

  const pack = game.packs.get(MUTATION_ITEM_PACK);
  if (!pack) throw new Error(`The required compendium ${MUTATION_ITEM_PACK} is unavailable.`);

  const sources = (await pack.getDocuments()).filter(isMutationItem);
  const sourcesById = new Map(sources.map((item) => [definitionId(item) ?? item.id, item]));
  const sourcesByName = new Map(sources.map((item) => [item.name, item]));

  const actors = collectMutationMigrationActors(game.actors ?? [], game.scenes ?? []);
  for (const actor of actors) {
    const updates: Record<string, unknown>[] = [];
    const effectMigrations: Array<{ owned: WfrpMutationItem; source: WfrpMutationItem }> = [];
    for (const owned of Array.from(actor.items).filter(isMutationItem)) {
      const source =
        (definitionId(owned) ? sourcesById.get(definitionId(owned) as string) : undefined) ??
        (isHandbookMutation(owned) ? sourcesByName.get(owned.name) : undefined);
      if (!source) continue;

      const update = prepareOwnedMutationAutomationUpdate(itemData(owned), itemData(source));
      if (!update) continue;

      if ("effects" in update) {
        effectMigrations.push({ owned, source });
        delete update["effects"];
      }
      if (Object.keys(update).length > 0) updates.push({ _id: owned.id, ...update });
    }

    if (updates.length > 0) await actor.updateEmbeddedDocuments("Item", updates);
    for (const migration of effectMigrations) {
      await replaceManagedEffects(migration.owned, migration.source);
    }
    await reconcileMutationAutomation(actor.uuid);
  }
}
