import type {
  MutationActionDefinition,
  MutationTimedEffect,
} from "../../../../functions/mutants-handbook/actions";
import { MODULE_ID } from "../../../constants";
import { activeMutationLevels } from "./documents";
import { mutationEffectDuration, mutationNumber, mutationScriptData } from "./effect-helpers";
import type { MutationActionActor, MutationActionTest } from "./types";

const FLIGHT_UUID = "Compendium.wfrp4e-core.items.Item.EO05HX7jql0g605A";

async function removeExistingActionDocuments(
  actor: MutationActionActor,
  type: "ActiveEffect" | "Item",
  actionId: string,
): Promise<void> {
  const documents = type === "ActiveEffect" ? actor.effects : actor.items;
  const ids = documents
    ? [...documents]
        .filter((document) => document.flags?.[MODULE_ID]?.["actionId"] === actionId)
        .map(({ id }) => id)
        .filter((id): id is string => typeof id === "string")
    : [];
  if (ids.length) await actor.deleteEmbeddedDocuments?.(type, ids);
}

function baseEffect(
  action: MutationActionDefinition,
  name: string,
  description: string,
): Record<string, unknown> {
  return {
    changes: [],
    description,
    disabled: false,
    duration: mutationEffectDuration(),
    flags: {
      [MODULE_ID]: { actionId: action.id, automationPhase: "mutation-phase-5" },
      wfrp4e: {},
    },
    img: "icons/svg/clockwork.svg",
    name,
    statuses: [],
    system: {
      scriptData: [],
      sourceData: {},
      transferData: {
        area: { aura: {} },
        avoidTest: { value: "none" },
        documentType: "Actor",
        equipTransfer: false,
        prompt: false,
        type: "document",
      },
      zone: {},
    },
    transfer: false,
    type: "base",
  };
}

function testValues(
  actor: MutationActionActor,
  action: MutationActionDefinition,
  test?: MutationActionTest,
) {
  const levels = Math.max(1, activeMutationLevels(actor, action.mutationId));
  return {
    levels,
    sl: mutationNumber(test?.result?.SL),
    wp: mutationNumber(actor.system?.characteristics?.["wp"]?.value),
    wpb: mutationNumber(actor.system?.characteristics?.["wp"]?.bonus),
  };
}

async function createFlight(
  actor: MutationActionActor,
  action: MutationActionDefinition,
  test?: MutationActionTest,
): Promise<void> {
  if (!actor.createEmbeddedDocuments) return;
  const { levels, sl, wpb } = testValues(actor, action, test);
  const rounds = Math.max(1, wpb + sl) * 2 ** (levels - 1);
  const resolver = Reflect.get(globalThis, "fromUuid") as
    | ((uuid: string) => Promise<{ toObject?: () => Record<string, unknown> } | undefined>)
    | undefined;
  const source = await resolver?.(FLIGHT_UUID);
  const data = source?.toObject?.();
  if (!data) return;
  await removeExistingActionDocuments(actor, "Item", action.id);
  delete data["_id"];
  data["name"] = `${action.mutationName} — Flight (${30 * levels})`;
  const system = (data["system"] ??= {}) as Record<string, unknown>;
  const specification = (system["specification"] ??= {}) as Record<string, unknown>;
  specification["value"] = String(30 * levels);
  const flags = (data["flags"] ??= {}) as Record<string, unknown>;
  flags[MODULE_ID] = { actionId: action.id, automationPhase: "mutation-phase-5", rounds };
  const effects = Array.isArray(data["effects"]) ? data["effects"] : [];
  effects.push({
    ...baseEffect(action, "Levitation duration", `Expires after ${rounds} rounds.`),
    system: {
      scriptData: [
        mutationScriptData(
          "Expire Mutant's Handbook outcome",
          "endRound",
          `const key = "flags.${MODULE_ID}.rounds";\nconst left = Number(this.item.getFlag("${MODULE_ID}", "rounds")) - 1;\nif (left <= 0) return this.item.delete();\nreturn this.item.update({[key]: left});`,
        ),
      ],
      sourceData: {},
      transferData: {
        area: { aura: {} },
        avoidTest: { value: "none" },
        documentType: "Actor",
        equipTransfer: false,
        prompt: false,
        type: "document",
      },
      zone: {},
    },
    transfer: true,
  });
  data["effects"] = effects;
  await actor.createEmbeddedDocuments("Item", [data]);
}

function configuredEffect(
  effect: MutationTimedEffect,
  actor: MutationActionActor,
  action: MutationActionDefinition,
  test?: MutationActionTest,
  sourceActor: MutationActionActor = actor,
): Record<string, unknown> {
  const { levels, sl, wp, wpb } = testValues(sourceActor, action, test);
  if (effect === "invisible") {
    const rounds = Math.max(1, wp + sl) * 2 ** (levels - 1);
    const data = baseEffect(
      action,
      "Invisible",
      "Ends early after an attack or conspicuously loud noise.",
    );
    data["duration"] = mutationEffectDuration(rounds);
    data["statuses"] = ["invisible"];
    data["img"] = "icons/svg/invisible.svg";
    return data;
  }
  if (effect === "entrancement") {
    const hours = Math.max(1, wpb + sl);
    const data = baseEffect(
      action,
      `${action.mutationName} — Entranced`,
      `The source mutant gains +20 to social interactions with this Actor for ${hours} hours.`,
    );
    data["duration"] = mutationEffectDuration(undefined, hours * 3600);
    return data;
  }
  if (effect === "camouflage") {
    const data = baseEffect(
      action,
      "Chameleon Camouflage (Scene)",
      "+20 to Stealth while the skin still matches the surroundings; delete when the scene changes.",
    );
    const system = data["system"] as Record<string, unknown>;
    system["scriptData"] = [
      mutationScriptData(
        "Expire Mutant's Handbook outcome",
        "dialog",
        `if (args.skill?.name?.toLowerCase().includes("stealth")) args.fields.modifier += 20;`,
      ),
      mutationScriptData(
        "Expire Mutant's Handbook outcome",
        "endCombat",
        "return this.effect.delete();",
      ),
    ];
    return data;
  }
  if (effect === "foresight") {
    const currentFortune = mutationNumber(
      (actor.system as Record<string, unknown> | undefined)?.["status"] &&
        ((actor.system as Record<string, unknown>)["status"] as Record<string, unknown>)["fortune"]
        ? (
            ((actor.system as Record<string, unknown>)["status"] as Record<string, unknown>)[
              "fortune"
            ] as Record<string, unknown>
          )["value"]
        : 0,
    );
    const data = baseEffect(
      action,
      "Oracle Foresight (Scene)",
      `+10 Initiative and ${levels} temporary Fortune; delete when the scene ends.`,
    );
    data["changes"] = [
      { key: "system.characteristics.i.modifier", mode: 2, priority: null, value: "10" },
    ];
    const system = data["system"] as Record<string, unknown>;
    system["scriptData"] = [
      mutationScriptData(
        "Expire Mutant's Handbook outcome",
        "endCombat",
        "return this.effect.delete();",
      ),
      mutationScriptData(
        "Expire Mutant's Handbook outcome",
        "deleteEffect",
        `const current = Number(this.actor.system.status.fortune.value);\nif (current > ${currentFortune}) return this.actor.update({"system.status.fortune.value": ${currentFortune}});`,
      ),
    ];
    const flags = data["flags"] as Record<string, Record<string, unknown>>;
    const moduleFlags = (flags[MODULE_ID] ??= {});
    moduleFlags["baseFortune"] = currentFortune;
    moduleFlags["fortune"] = levels;
    return data;
  }
  const rounds = Math.max(1, wp);
  if (effect === "temporal-surge") {
    const data = baseEffect(
      action,
      "Temporal Surge (This Turn)",
      "One additional Movement and Action are available during the current turn.",
    );
    data["duration"] = mutationEffectDuration();
    const system = data["system"] as Record<string, unknown>;
    system["scriptData"] = [
      mutationScriptData(
        "Expire Mutant's Handbook outcome",
        "endTurn",
        "return this.effect.delete();",
      ),
    ];
    return data;
  }
  const data = baseEffect(
    action,
    "Telekinesis Active",
    `May move matter at WPB yards per round for ${rounds} rounds.`,
  );
  data["duration"] = mutationEffectDuration(rounds);
  return data;
}

export async function applyTimedMutationEffect(
  effect: MutationTimedEffect,
  actor: MutationActionActor,
  action: MutationActionDefinition,
  test?: MutationActionTest,
  sourceActor: MutationActionActor = actor,
): Promise<void> {
  if (effect === "levitation") return createFlight(actor, action, test);
  await removeExistingActionDocuments(actor, "ActiveEffect", action.id);
  const data = configuredEffect(effect, actor, action, test, sourceActor);
  await actor.createEmbeddedDocuments?.("ActiveEffect", [data]);
  if (effect === "foresight") {
    const levels = Math.max(1, activeMutationLevels(actor, action.mutationId));
    const status = (actor.system as Record<string, unknown> | undefined)?.["status"] as
      | Record<string, unknown>
      | undefined;
    const fortune = status?.["fortune"] as Record<string, unknown> | undefined;
    const current = mutationNumber(fortune?.["value"]);
    await actor.update?.({ "system.status.fortune.value": current + levels });
  }
}
